<?php
declare(strict_types=1);
require dirname(__DIR__) . '/app/bootstrap.php';
$user=requireLogin();require_once BASE_PATH.'/includes/rental-operations-common.php';ro_require_permission('invoices.manage');$pdo=Database::connection();
if(is_post()){ro_post_guard();try{$id=RentalOperations::createInvoiceForRental($pdo,(int)($_POST['rental_id']??0),isset($user['user_id'])?(int)$user['user_id']:null);ro_flash('success','Invoice generated or existing invoice opened.');redirect('admin/invoice-view.php?id='.$id);}catch(Throwable $e){ro_flash('danger',$e->getMessage());redirect('admin/invoices.php');}}
$pageTitle='Invoices';$currentPage='invoices';
$ready=$pdo->query("SELECT r.rental_id,r.rental_number,r.status,r.final_amount,c.first_name,c.last_name,v.make,v.model,v.registration_no FROM rentals r JOIN customers c ON c.customer_id=r.customer_id JOIN vehicles v ON v.vehicle_id=r.vehicle_id LEFT JOIN invoices i ON i.rental_id=r.rental_id AND i.status<>'void' WHERE r.status IN ('returned','inspected','closed') AND i.invoice_id IS NULL ORDER BY r.actual_return_datetime DESC")->fetchAll(PDO::FETCH_ASSOC);
$invoices=$pdo->query('SELECT i.invoice_id,i.invoice_number,i.issue_date,i.due_date,i.total_amount,i.currency,i.status,c.first_name,c.last_name,r.rental_number,b.total_paid_gross,b.total_refunded,b.outstanding_balance FROM invoices i JOIN customers c ON c.customer_id=i.customer_id LEFT JOIN rentals r ON r.rental_id=i.rental_id JOIN vw_invoice_balances b ON b.invoice_id=i.invoice_id ORDER BY i.invoice_id DESC LIMIT 200')->fetchAll(PDO::FETCH_ASSOC);
require BASE_PATH.'/includes/header.php';require BASE_PATH.'/includes/rental-operations-nav.php';
?>
<div class="ro-shell"><section class="ro-page-heading"><div><span class="ro-kicker">BILLING & RECEIVABLES</span><h1>Invoices</h1><p>Generate itemized bills from returned rentals, issue invoices, and track payments against each balance.</p></div><div class="ro-heading-symbol"><i class="bi bi-receipt-cutoff"></i></div></section>
<?php if($ready): ?><section class="ro-panel mb-4"><div class="ro-panel-head"><div><span class="ro-kicker">READY TO BILL</span><h2>Completed rental charges</h2></div><span class="ro-counter"><?= count($ready) ?> unbilled</span></div><div class="table-responsive"><table class="table ro-table align-middle"><thead><tr><th>Rental</th><th>Customer</th><th>Vehicle</th><th>Final amount</th><th></th></tr></thead><tbody><?php foreach($ready as $r): ?><tr><td><strong><?= e($r['rental_number']) ?></strong><?= ro_status_badge($r['status']) ?></td><td><?= e($r['first_name'].' '.$r['last_name']) ?></td><td><?= e($r['make'].' '.$r['model'].' · '.$r['registration_no']) ?></td><td><strong><?= ro_money($r['final_amount']) ?></strong></td><td><form method="post"><?= csrf_field() ?><input type="hidden" name="rental_id" value="<?= (int)$r['rental_id'] ?>"><button class="btn ro-btn-primary" type="submit"><i class="bi bi-receipt me-1"></i> Generate invoice</button></form></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
<section class="ro-panel"><div class="ro-panel-head"><div><span class="ro-kicker">INVOICE REGISTER</span><h2>All invoices</h2></div><span class="ro-counter"><?= count($invoices) ?> records</span></div><?php if(!$invoices): ?><div class="ro-empty"><div class="ro-empty-icon"><i class="bi bi-receipt"></i></div><strong>No invoices yet</strong><p>Returned rentals will appear above when ready to bill.</p></div><?php else: ?><div class="table-responsive"><table class="table ro-table align-middle"><thead><tr><th>Invoice</th><th>Customer</th><th>Rental</th><th>Issued</th><th>Due</th><th>Total</th><th>Paid net</th><th>Balance</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($invoices as $i): ?><tr><td><strong><?= e($i['invoice_number']) ?></strong></td><td><?= e($i['first_name'].' '.$i['last_name']) ?></td><td><?= e($i['rental_number']?:'—') ?></td><td><?= e(ro_date($i['issue_date'])) ?></td><td><?= e(ro_date($i['due_date'])) ?></td><td><?= ro_money($i['total_amount'],$i['currency']) ?></td><td><?= ro_money(max(0,(float)$i['total_paid_gross']-(float)$i['total_refunded']),$i['currency']) ?></td><td><strong><?= ro_money($i['outstanding_balance'],$i['currency']) ?></strong></td><td><?= ro_status_badge($i['status']) ?></td><td><a class="btn btn-sm ro-btn-outline" href="<?= e(base_url('admin/invoice-view.php?id='.(int)$i['invoice_id'])) ?>">Open <i class="bi bi-arrow-up-right"></i></a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section></div>
<?php require BASE_PATH.'/includes/footer.php'; ?>
